:root {
  --bg: #04060f;
  --bg-2: #071021;
  --cyan: #45e8ff;
  --cyan-soft: #a6f7ff;
  --cyan-deep: #0bb4dc;
  --magenta: #ff3d86;
  --magenta-soft: #ff9ac0;
  --gold: #ffd36e;
  --gold-deep: #d8982f;
  --violet: #9b7bff;
  --green: #5dffaf;
  --text: #f0f8ff;
  --muted: #8ba4bf;
  --dim: #5d7188;
  --line: rgba(128, 220, 255, .17);
  --line-bright: rgba(128, 230, 255, .45);
  --panel: rgba(7, 14, 28, .74);
  --panel-2: rgba(11, 20, 39, .86);
  --hand-h: clamp(106px, 16vh, 146px);
  --hand-w: calc(var(--hand-h) * .715);
  --bottom-h: calc(var(--hand-h) + 34px);
  --shadow-cyan: 0 0 26px rgba(69, 232, 255, .32);
  --shadow-magenta: 0 0 26px rgba(255, 61, 134, .32);
  --ease-out: cubic-bezier(.16, .84, .3, 1);
  --ease-snap: cubic-bezier(.2, 1.4, .4, 1);
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--bg);
  color: var(--text);
  font-family: "Helvetica Neue", "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  -webkit-font-smoothing: antialiased;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}

button { font: inherit; color: inherit; }
button, [role="button"] { -webkit-tap-highlight-color: transparent; }
[hidden] { display: none !important; }
svg { display: block; }

#cosmos {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

.ambient {
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  opacity: .65;
  filter: blur(10px);
}

.ambient-a {
  background:
    radial-gradient(circle at 20% 30%, rgba(16, 101, 147, .17), transparent 32%),
    radial-gradient(circle at 75% 78%, rgba(103, 26, 91, .13), transparent 34%);
}

.ambient-b {
  background:
    linear-gradient(115deg, transparent 0 38%, rgba(69, 232, 255, .025) 45%, transparent 52%),
    linear-gradient(295deg, transparent 0 42%, rgba(255, 61, 134, .025) 49%, transparent 56%);
  animation: ambient-drift 18s ease-in-out infinite alternate;
}

.scanlines {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: .16;
  background: repeating-linear-gradient(to bottom, transparent 0 3px, rgba(0, 0, 0, .22) 3px 4px);
  mix-blend-mode: multiply;
}

@keyframes ambient-drift {
  from { transform: translate3d(-1.5%, -1%, 0) scale(1); }
  to { transform: translate3d(1.5%, 1%, 0) scale(1.04); }
}

/* ───────────────────────── APP SHELL ───────────────────────── */

.app {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-rows: 54px minmax(0, 1fr) var(--bottom-h);
  height: 100%;
  height: 100dvh;
  max-width: 1800px;
  margin: 0 auto;
  padding: max(6px, env(safe-area-inset-top)) max(10px, env(safe-area-inset-right)) max(8px, env(safe-area-inset-bottom)) max(10px, env(safe-area-inset-left));
  transition: opacity .55s var(--ease-out), filter .55s var(--ease-out);
}

body.preduel .app {
  opacity: .24;
  filter: blur(3px) saturate(.65);
  pointer-events: none;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
  padding: 0 3px;
}

  color: var(--cyan-soft);
  border-color: rgba(69, 232, 255, .5);
  background: rgba(12, 32, 54, .72);
  outline: none;
}

.hero-foot {
  margin: 15px 0 0;
  color: var(--dim);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .28em;
}

.landing-footer {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 12px 6px 2px;
  border-top: 1px solid rgba(128, 220, 255, .1);
  color: var(--dim);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .2em;
}

/* ───────────────────────── DUEL LAYOUT ───────────────────────── */

.duel-layout {
  display: grid;
  grid-template-columns: 228px minmax(0, 1fr) 228px;
  align-items: stretch;
  gap: clamp(8px, 1.1vw, 18px);
  min-height: 0;
  padding: 4px 0;
}

.duelist-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 16px 15px 13px;
  border: 1px solid rgba(128, 220, 255, .15);
  background:
    linear-gradient(140deg, rgba(255, 255, 255, .045), transparent 27%),
    linear-gradient(180deg, rgba(9, 20, 39, .88), rgba(5, 10, 21, .8));
  clip-path: polygon(0 13px, 13px 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  overflow: hidden;
  transition: border-color .3s, box-shadow .3s, opacity .3s;
}

.duelist-panel::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: linear-gradient(180deg, transparent, var(--accent, var(--cyan)), transparent);
  opacity: .9;
}

.duelist-panel.is-active {
  border-color: rgba(69, 232, 255, .38);
  box-shadow: inset 0 0 38px rgba(69, 232, 255, .045), 0 0 30px rgba(69, 232, 255, .07);
}

.rival-panel { --accent: var(--magenta); }
.player-panel { --accent: var(--cyan); }

.rival-panel.is-active {
  border-color: rgba(255, 61, 134, .4);
  box-shadow: inset 0 0 38px rgba(255, 61, 134, .045), 0 0 30px rgba(255, 61, 134, .08);
}

.panel-scan {
  position: absolute;
  left: 0;
  right: 0;
  top: -10%;
  height: 30%;
  background: linear-gradient(180deg, transparent, rgba(69, 232, 255, .035), transparent);
  animation: panel-scan 7s linear infinite;
  pointer-events: none;
}

.rival-panel .panel-scan { background: linear-gradient(180deg, transparent, rgba(255, 61, 134, .035), transparent); }

@keyframes panel-scan {
  from { transform: translateY(-100%); }
  to { transform: translateY(460%); }
}

.duelist-head {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}


.rival-hand {
  display: flex;
  justify-content: center;
  height: 44px;
  margin-top: 13px;
  padding-top: 2px;
}

.mini-back {
  width: 23px;
  height: 33px;
  margin-left: -7px;
  border: 1px solid rgba(255, 61, 134, .3);
  border-radius: 2px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .11), transparent 36%),
    repeating-linear-gradient(45deg, transparent 0 4px, rgba(255, 61, 134, .08) 4px 5px),
    #160a1c;
  transform: rotate(var(--r, 0deg)) translateY(var(--y, 0px));
  box-shadow: 0 2px 5px rgba(0, 0, 0, .35);
}

.mini-back:first-child { margin-left: 0; }

/* ───────────────────────── BOARD ───────────────────────── */

.board-shell {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: min(100%, 760px, calc(100dvh * .87));
  min-width: 0;
  margin: 0 auto;
  perspective: 1400px;
}

.board-crown {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 20px;
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .25em;
}

.crown-line { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, rgba(69, 232, 255, .35)); }
.crown-line:last-child { transform: scaleX(-1); }
.crown-label { white-space: nowrap; color: var(--gold); text-shadow: 0 0 12px rgba(255, 211, 110, .35); }

.board {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  min-height: 0;
  flex: 1;
  padding: 12px clamp(8px, 1.3vw, 15px);
  border: 1px solid rgba(128, 220, 255, .16);
  background:
    radial-gradient(ellipse at 50% 50%, rgba(24, 77, 115, .22), transparent 55%),
    linear-gradient(150deg, rgba(255, 255, 255, .025), transparent 30%),
    rgba(4, 9, 20, .72);
  box-shadow:
    inset 0 0 80px rgba(0, 0, 0, .55),
    inset 0 0 42px rgba(69, 232, 255, .035),
    0 18px 70px rgba(0, 0, 0, .4);
  clip-path: polygon(16px 0, calc(100% - 16px) 0, 100% 16px, 100% calc(100% - 16px), calc(100% - 16px) 100%, 16px 100%, 0 calc(100% - 16px), 0 16px);
  overflow: hidden;
}

.board-grid {
  position: absolute;
  inset: 0;
  opacity: .22;
  background-image:
    linear-gradient(rgba(69, 232, 255, .1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(69, 232, 255, .1) 1px, transparent 1px);
  background-size: 32px 32px;
  mask-image: radial-gradient(ellipse at center, #000 15%, transparent 78%);
  pointer-events: none;
}

.board-orbit {
  position: absolute;
  left: 50%;
  top: 50%;
  border: 1px solid rgba(69, 232, 255, .08);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.orbit-one { width: 56%; aspect-ratio: 1; box-shadow: 0 0 0 22px rgba(69, 232, 255, .008); }
.orbit-two { width: 30%; aspect-ratio: 1; border-style: dashed; border-color: rgba(255, 211, 110, .08); animation: ring-spin 40s linear infinite; }

.side-tag {
