.card-position.def { color: var(--gold); }

.card.is-opponent.card.is-face-down { border-color: rgba(255, 61, 134, .4); }

.card.exhausted { filter: saturate(.4) brightness(.64); }
.card.exhausted::before { opacity: .1; }
.card.attacking { z-index: 20; animation: card-attack .42s var(--ease-snap); }
.card.destroying { animation: card-destroy .48s forwards; }

@keyframes card-attack {
  0% { transform: translateY(0) scale(1); filter: brightness(1); }
  35% { transform: translateY(-10px) scale(1.08); filter: brightness(1.7); }
  100% { transform: translateY(0) scale(1); filter: brightness(1); }
}

@keyframes card-destroy {
  0% { transform: scale(1); filter: brightness(1.8); opacity: 1; }
  45% { transform: scale(1.06) rotate(2deg); filter: brightness(2.2); opacity: .9; }
  100% { transform: scale(.5) rotate(-7deg); filter: brightness(.2); opacity: 0; }
